// A simple matrix type: Vec of rows, each row is Vec<T>.
pub type Matrix<T> = Vec<Vec<T>>;

pub fn broadcast(a: Vec<i8>, shape: Vec<u8>) -> Matrix<i8> {
    // Assumptions say: a.len() > 0, shape.len() == 2, R > 0, C > 0,
    // and a.len() == R or a.len() == C (at least one matches).
    let r = shape[0] as usize;
    let c = shape[1] as usize;
    let n = a.len();

    if r == n {
        // Treat `a` as a column vector; replicate each a[i] across columns.
        let mut ret: Matrix<i8> = Vec::with_capacity(r);
        for i in 0..r {
            ret.push(vec![a[i]; c]);
        }
        ret
    } else {
        // Otherwise C must match; treat `a` as a row vector; duplicate for each row.
        // (Per problem statement, this branch is valid because at least one dimension matches.)
        let mut ret: Matrix<i8> = Vec::with_capacity(r);
        for _ in 0..r {
            ret.push(a.clone());
        }
        ret
    }
}